function build(arr){ var n=arr.length; var t=new Array(2*n).fill(0);
  for(var i=0;i<n;i++) t[n+i]=arr[i];
  for(var i=n-1;i>0;i--) t[i]=t[2*i]+t[2*i+1];
  return {t:t,n:n}; }
function query(st,l,r){ var t=st.t,n=st.n,res=0; l+=n; r+=n;
  while(l<=r){ if(l%2===1) res+=t[l++]; if(r%2===0) res+=t[r--]; l=Math.floor(l/2); r=Math.floor(r/2); } return res; }
function update(st,i,v){ var t=st.t,n=st.n; i+=n; t[i]=v; for(i=Math.floor(i/2);i>0;i=Math.floor(i/2)) t[i]=t[2*i]+t[2*i+1]; }
var EXPORTS = { build:build, query:query, update:update };

